// Function to transfer user and change password
public void transferUserAndChangePassword(String userID, String newDepartmentId, String newPassword) {
    DirectoryManager directoryManager = (DirectoryManager) AppUtil.getApplicationContext().getBean("directoryManager");
    EmploymentDao employmentDao = (EmploymentDao) AppUtil.getApplicationContext().getBean("employmentDao");
    UserDao userDao = (UserDao) AppUtil.getApplicationContext().getBean("userDao");

    // Get the user by user ID (which is email in your use-case)
    User user = userDao.getUser(userID); // Assumes userID = email
    if (user == null) {
        LogUtil.info("transferUserAndChangePassword", "User not found: " + userID);
        return;
    }

    // Unassign and reassign department
    employmentDao.unassignUserFromDepartment(user.getId(), "organisme_pass");
    employmentDao.assignUserToDepartment(user.getId(), newDepartmentId);

    // Update password
    user.setPassword(newPassword);
    userDao.updateUser(user);
    
    LogUtil.info("transferUserAndChangePassword", "User transferred and password changed for: " + userID);
}

